+  /**
+   * Tracks generated declarations which a source file can conditionally retain. References are collected from a
+   * complete output pass, so declarations omitted in that pass cannot contribute references. Repeating until no new
+   * declaration is retained computes the least fixed point rooted in code that was going to be emitted anyway.
+   */
+  private static final class ReferenceRetentionContext {
+    private final Set<GeneratedMemberKey> candidates = new HashSet<>();
+    private final Set<GeneratedMemberKey> retained = new HashSet<>();
+    private final Map<GeneratedMemberKey, List<GeneratedMemberKey>> enclosingCandidates = new HashMap<>();
+    private final Set<ClassNode> processed = Collections.newSetFromMap(new IdentityHashMap<>());
+    private final String methodToDecompile;
+
+    private ReferenceRetentionContext(ClassNode root) {
+      methodToDecompile = (String)DecompilerContext.getProperty(IFernflowerPreferences.METHOD_TO_DECOMPILE);
+      collectCandidates(root, List.of());
+    }
+
+    private boolean markProcessed(ClassNode node) {
+      return processed.add(node);
+    }
+
+    private boolean isRetained(GeneratedMemberKey key) {
+      return candidates.contains(key) && retained.contains(key);
+    }
+
+    private boolean retainReferencesFrom(TextBuffer buffer) {
+      boolean changed = false;
+      for (TextToken token : buffer.getTokens()) {
+        if (token.isDeclaration()) {
+          continue;
+        }
+
+        GeneratedMemberKey key = null;
+        if (token instanceof FieldTextToken field) {
+          key = GeneratedMemberKey.field(field.className, field.name, field.descriptor.descriptorString);
+        }
+        else if (token instanceof MethodTextToken method) {
+          key = GeneratedMemberKey.method(method.className, method.name, method.descriptor.toString());
+        }
+        else if (token instanceof ClassTextToken clazz) {
+          key = GeneratedMemberKey.clazz(clazz.qualifiedName);
+        }
+
+        if (key != null && candidates.contains(key)) {
+          changed |= retain(key);
+        }
+      }
+      return changed;
+    }
+
+    private boolean retain(GeneratedMemberKey key) {
+      boolean changed = retained.add(key);
+      for (GeneratedMemberKey enclosing : enclosingCandidates.getOrDefault(key, List.of())) {
+        changed |= retain(enclosing);
+      }
+      return changed;
+    }
+
+    private void addCandidate(GeneratedMemberKey key, List<GeneratedMemberKey> enclosing) {
+      candidates.add(key);
+      enclosingCandidates.put(key, List.copyOf(enclosing));
+    }
+
+    private void collectCandidates(ClassNode node, List<GeneratedMemberKey> enclosing) {
+      if (node.type == ClassNode.Type.LAMBDA) {
+        return;
+      }
+
+      ClassWrapper wrapper = node.getWrapper();
+      if (wrapper == null) {
+        return;
+      }
+
+      StructClass cl = wrapper.getClassStruct();
+      List<GeneratedMemberKey> contentsEnclosing = enclosing;
+      if (node.type == ClassNode.Type.MEMBER && methodToDecompile.isEmpty()) {
+        boolean synthetic = (node.access & CodeConstants.ACC_SYNTHETIC) != 0 || cl.isSynthetic();
+        boolean hidden = synthetic && DecompilerContext.getOption(IFernflowerPreferences.REMOVE_SYNTHETIC) ||
+          node.parent != null && node.parent.getWrapper().getHiddenMembers().contains(cl.qualifiedName);
+        if (synthetic && hidden) {
+          GeneratedMemberKey key = GeneratedMemberKey.clazz(cl.qualifiedName);
+          addCandidate(key, enclosing);
+          contentsEnclosing = new ArrayList<>(enclosing);
+          contentsEnclosing.add(key);
+        }
+      }
+
+      if (methodToDecompile.isEmpty()) {
+        for (StructField field : cl.getFields()) {
+          boolean enumField = field.hasModifier(CodeConstants.ACC_ENUM) &&
+            DecompilerContext.getOption(IFernflowerPreferences.DECOMPILE_ENUM);
+          boolean hidden = field.isSynthetic() && DecompilerContext.getOption(IFernflowerPreferences.REMOVE_SYNTHETIC) ||
+            wrapper.getHiddenMembers().contains(InterpreterUtil.makeUniqueKey(field.getName(), field.getDescriptor()));
+          if (!enumField && field.isSynthetic() && hidden) {
+            addCandidate(GeneratedMemberKey.field(cl.qualifiedName, field), contentsEnclosing);
+          }
+        }
+      }
+
+      if (methodToDecompile.isEmpty() || (node.type != ClassNode.Type.ROOT && node.type != ClassNode.Type.MEMBER)) {
+        for (StructMethod method : cl.getMethods()) {
+          boolean generated = method.isSynthetic() || method.hasModifier(CodeConstants.ACC_BRIDGE);
+          boolean hidden = method.isSynthetic() && DecompilerContext.getOption(IFernflowerPreferences.REMOVE_SYNTHETIC) ||
+            method.hasModifier(CodeConstants.ACC_BRIDGE) && DecompilerContext.getOption(IFernflowerPreferences.REMOVE_BRIDGE) ||
+            wrapper.getHiddenMembers().contains(InterpreterUtil.makeUniqueKey(method.getName(), method.getDescriptor()));
+          if (generated && hidden) {
+            addCandidate(GeneratedMemberKey.method(cl.qualifiedName, method), contentsEnclosing);
+          }
+        }
+      }
+
+      for (ClassNode child : node.nested) {
+        collectCandidates(child, contentsEnclosing);
+      }
+    }
+  }
*** End Patch";
